package com.hbm.missile.launchpad.large;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.registries.*;
public final class LargeLaunchPadContent{private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");public static final DeferredBlock<LargeLaunchPadBlock> BLOCK=BLOCKS.register("launch_pad_large",LargeLaunchPadBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem("launch_pad_large",BLOCK);public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<LargeLaunchPadBlockEntity>> ENTITY=ENTITIES.register("launch_pad_large",()->BlockEntityType.Builder.of(LargeLaunchPadBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<LargeLaunchPadPort>> PORT=ENTITIES.register("launch_pad_large_port",()->BlockEntityType.Builder.of(LargeLaunchPadPort::new,BLOCK.get()).build(null));public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);bus.addListener(LargeLaunchPadContent::capabilities);}private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(be,side)->side==null?new InvWrapper(be):new SidedInvWrapper(be,side));event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,PORT.get(),(be,side)->side==null?new InvWrapper(be):new SidedInvWrapper(be,side));}public static List<ItemStack> creativeStacks(String tab){return tab.equals("missile")?List.of(new ItemStack(ITEM.get())):List.of();}private LargeLaunchPadContent(){}}
